  bar([MAST_X + HALF, y, -HALF], [MAST_X + HALF, y, HALF], 0.1);
}
for (let k = 0; k < levels; k += 1) {
  const y0 = lvl(k);
  const y1 = lvl(k + 1);
  const flip = k % 2 === 0 ? 1 : -1;
  bar([MAST_X - HALF * flip, y0, HALF], [MAST_X + HALF * flip, y1, HALF], 0.08);
